[{'name': 'Todeszahlen', 'text': 'Spektakel {B}
Ziehe für jede Kreatur, die in diesem Zug unter deiner Kontrolle gestorben ist, eine Karte.', 'type': 'Spontanzauber', 'flavor': None, 'imageUrl': 'http://gatherer.wizards.com/Handlers/Image.ashx?multiverseid=562520&type=card', 'language': 'German', 'identifiers': {'scryfallId': '672cbdd6-ebda-4b31-b28a-b830811881be', 'multiverseId': 562520}, 'multiverseid': 562520}, {'name': 'Décompte des corps', 'text': 'Spectacle {B}
